def get_total_number_of_sequences(m, n):
    # Initialize the table with zeros
    dp = [[0 for _ in range(n+1)] for _ in range(m+1)]

    # Base case: There's one sequence of length 0 for any m
    for i in range(m+1):
        dp[i][0] = 1

    # Fill the table
    for length in range(1, n+1):
        for start in range(1, m+1):
            dp[start][length] = 0
            for elem in range(2*start, m+1):
                dp[start][length] += dp[elem][length-1]

    # The answer is the sum of sequences of length n starting with any number from 1 to m
    return sum(dp[i][n] for i in range(1, m+1))

